<?php
require_once 'config.php';require_login();$pdo=db();$message='';$edit=null;
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();require_role(['admin','treasurer']);$action=$_POST['action']??'save';$id=(int)($_POST['id']??0);
 if($action==='delete'){$q=$pdo->prepare('SELECT * FROM transactions WHERE id=?');$q->execute([$id]);$old=$q->fetch();if($old){if(period_locked((int)$old['account_id'],$old['tx_date']))$message='Suppression refusée : ce mois est clôturé.';else{$d=$pdo->prepare('DELETE FROM transactions WHERE id=?');$d->execute([$id]);audit('DELETE','transactions',$id,json_encode($old,JSON_UNESCAPED_UNICODE));$message='Opération supprimée et journalisée.';}}}
 else{$account=(int)($_POST['account_id']??0);$cat=(int)($_POST['category_id']??0) ?: null;$date=$_POST['tx_date']??'';$type=$_POST['type']??'';$cur=$_POST['currency']??'';$amount=(float)str_replace(',','.',$_POST['amount']??'0');$label=trim($_POST['label']??'');$desc=null;if($amount<=0||!in_array($type,['income','expense'],true)||!in_array($cur,['USD','FC'],true)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||$label==='')$message='Vérifiez les informations saisies.';elseif(!$pdo->query('SELECT id FROM accounts WHERE id='.(int)$account.' AND active=1')->fetchColumn())$message='Compte invalide ou désactivé.';elseif($cat!==null&&!(function()use($pdo,$cat,$account,$type){$q=$pdo->prepare('SELECT COUNT(*) FROM categories WHERE id=? AND (account_id=? OR account_id IS NULL) AND (kind=? OR kind=\'both\')');$q->execute([$cat,$account,$type]);return (int)$q->fetchColumn()>0;})())$message='La catégorie sélectionnée ne correspond pas au compte ou au type d’opération.';elseif(period_locked($account,$date))$message='Ce mois est clôturé. Demandez à un administrateur de le déverrouiller.';else{if($id){$oldq=$pdo->prepare('SELECT * FROM transactions WHERE id=?');$oldq->execute([$id]);$old=$oldq->fetch();if(!$old||period_locked((int)$old['account_id'],$old['tx_date']))$message='Modification refusée : opération introuvable ou mois clôturé.';else{$q=$pdo->prepare('UPDATE transactions SET account_id=?,category_id=?,tx_date=?,type=?,currency=?,amount=?,label=?,description=?,updated_by=?,updated_at=NOW() WHERE id=?');$q->execute([$account,$cat,$date,$type,$cur,$amount,$label,$desc,$_SESSION['user_id'],$id]);audit('UPDATE','transactions',$id,json_encode(['avant'=>$old,'apres'=>$_POST],JSON_UNESCAPED_UNICODE));$message='Opération modifiée.';}}else{$q=$pdo->prepare('INSERT INTO transactions(account_id,category_id,tx_date,type,currency,amount,label,description,created_by) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$account,$cat,$date,$type,$cur,$amount,$label,$desc,$_SESSION['user_id']]);$id=(int)$pdo->lastInsertId();audit('CREATE','transactions',$id,$label);$message='Opération enregistrée.';}}}}
if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM transactions WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$accounts=$pdo->query('SELECT * FROM accounts WHERE active=1 ORDER BY name')->fetchAll();$cats=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$search=trim($_GET['search']??'');$catfilter=0;$typefilter=$_GET['type']??'';$params=[$from,$to];$where='t.tx_date BETWEEN ? AND ?';if($search!==''){$where.=' AND (t.label LIKE ? OR t.description LIKE ?)';array_push($params,'%'.$search.'%','%'.$search.'%');}if(in_array($typefilter,['income','expense'],true)){$where.=' AND t.type=?';$params[]=$typefilter;}
$q=$pdo->prepare("SELECT t.*,a.name account_name,c.name category_name,u.full_name creator FROM transactions t JOIN accounts a ON a.id=t.account_id LEFT JOIN categories c ON c.id=t.category_id LEFT JOIN users u ON u.id=t.created_by WHERE $where ORDER BY t.tx_date DESC,t.id DESC LIMIT 1000");$q->execute($params);$rows=$q->fetchAll();$page_title='Recettes et dépenses';include 'partials/header.php';?>
<?php if($message):?><div class="notice"><?=h($message)?></div><?php endif?>
<div class="panel"><h2><?= $edit?'Modifier une opération':'Enregistrer une opération'?></h2><p>Les périodes clôturées sont protégées. Seuls les administrateurs et trésoriers peuvent saisir.</p><?php if(in_array(role(),['admin','treasurer'],true)):?><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=h($edit['id']??0)?>"><div><label>Compte</label><select name="account_id" required><?php foreach($accounts as $a):?><option value="<?=$a['id']?>" <?=($edit['account_id']??'')==$a['id']?'selected':''?>><?=h($a['name'])?></option><?php endforeach?></select></div><div><label>Catégorie (facultative)</label><select name="category_id" id="transactionCategory"><option value="">— Sans catégorie —</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" data-account="<?=$c['account_id']?>" data-kind="<?=h($c['kind'])?>" <?=($edit['category_id']??'')==$c['id']?'selected':''?>><?=h($c['name'])?></option><?php endforeach?></select></div><div><label>Date</label><input type="date" name="tx_date" value="<?=h($edit['tx_date']??date('Y-m-d'))?>" required></div><div><label>Type</label><select name="type"><option value="income" <?=($edit['type']??'')==='income'?'selected':''?>>Recette / Entrée</option><option value="expense" <?=($edit['type']??'')==='expense'?'selected':''?>>Dépense / Sortie</option></select></div><div><label>Devise</label><select name="currency"><option value="USD" <?=($edit['currency']??'')==='USD'?'selected':''?>>Dollar ($)</option><option value="FC" <?=($edit['currency']??'FC')==='FC'?'selected':''?>>Franc congolais (FC)</option></select></div><div><label>Montant</label><input type="number" name="amount" min="0.01" step="0.01" value="<?=h($edit['amount']??'')?>" required></div><div class="span-2"><label>Libellé</label><input name="label" value="<?=h($edit['label']??'')?>" required></div><div class="span-2"><button class="btn primary">Enregistrer</button> <?php if($edit):?><a class="btn" href="transactions.php">Annuler</a><?php endif?></div></form><?php else:?><p>Votre rôle permet uniquement la consultation.</p><?php endif?></div>
<div class="panel"><div class="panel-head"><div><h2>Historique et recherche</h2><p>Filtrez les dépenses de carburant par mois, trimestre ou année.</p></div><a class="btn" href="export.php?from=<?=h($from)?>&to=<?=h($to)?>&search=<?=urlencode($search)?>&cat=<?=$catfilter?>&type=<?=h($typefilter)?>">Exporter Excel (CSV)</a></div><form class="filter-row"><input type="date" id="dateFrom" name="from" value="<?=h($from)?>"><input type="date" id="dateTo" name="to" value="<?=h($to)?>"><button type="button" class="btn" onclick="quickPeriod('month')">Mois</button><button type="button" class="btn" onclick="quickPeriod('quarter')">Trimestre</button><button type="button" class="btn" onclick="quickPeriod('year')">Année</button><input name="search" placeholder="Carburant, libellé..." value="<?=h($search)?>"><select name="type"><option value="">Entrées et sorties</option><option value="expense" <?=$typefilter==='expense'?'selected':''?>>Dépenses seulement</option><option value="income" <?=$typefilter==='income'?'selected':''?>>Recettes seulement</option></select><button class="btn">Rechercher</button></form><div class="table-wrap"><table><thead><tr><th>Date</th><th>Compte</th><th>Type</th><th>Catégorie</th><th>Libellé</th><th>Devise</th><th>Montant</th><th>Enregistré par</th><th class="no-print">Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=date('d/m/Y',strtotime($r['tx_date']))?></td><td><?=h($r['account_name'])?></td><td><?=h($r['type']==='income'?'Entrée':'Sortie')?></td><td><?=h($r['category_name']??'—')?></td><td><?=h($r['label'])?></td><td><?=$r['currency']?></td><td class="num"><?=money($r['amount'],$r['currency'])?></td><td><?=h($r['creator']??'—')?></td><td class="no-print"><?php if(in_array(role(),['admin','treasurer'],true)&&!period_locked((int)$r['account_id'],$r['tx_date'])):?><a href="?edit=<?=$r['id']?>">Modifier</a> <form method="post" style="display:inline" onsubmit="return confirm('Confirmer la suppression ?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="link-danger">Supprimer</button></form><?php else:?>Verrouillé<?php endif?></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="9" class="empty">Aucune opération trouvée.</td></tr><?php endif?></tbody></table></div></div><script>const accountSelect=document.querySelector('select[name=account_id]'),categorySelect=document.getElementById('transactionCategory'),typeSelect=document.querySelector('select[name=type]');function filterCategories(){if(!categorySelect)return;const account=accountSelect?.value,type=typeSelect?.value;for(const option of categorySelect.options){if(!option.value)continue;const accountValid=option.dataset.account===account||option.dataset.account==='null'||option.dataset.account==='',kindValid=option.dataset.kind==='both'||option.dataset.kind===type,valid=accountValid&&kindValid;option.hidden=!valid;if(!valid&&option.selected)option.selected=false;}}accountSelect?.addEventListener('change',filterCategories);typeSelect?.addEventListener('change',filterCategories);filterCategories();function quickPeriod(p){const now=new Date(),y=now.getFullYear(),m=now.getMonth();let a,b;if(p==='month'){a=new Date(y,m,1);b=new Date(y,m+1,0)}else if(p==='quarter'){const q=Math.floor(m/3)*3;a=new Date(y,q,1);b=new Date(y,q+3,0)}else{a=new Date(y,0,1);b=new Date(y,11,31)}const fmt=d=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');document.getElementById('dateFrom').value=fmt(a);document.getElementById('dateTo').value=fmt(b)}</script><?php include 'partials/footer.php';?>